document.addEventListener('DOMContentLoaded', () => {
  const menuButton = document.querySelector('[data-hg-manager-menu]');
  const mobileNav = document.getElementById('hg-manager-mobile-nav');
  if (menuButton && mobileNav) {
    menuButton.addEventListener('click', () => {
      const open = mobileNav.hasAttribute('hidden');
      if (open) mobileNav.removeAttribute('hidden'); else mobileNav.setAttribute('hidden', '');
      menuButton.setAttribute('aria-expanded', open ? 'true' : 'false');
    });
  }

  document.querySelectorAll('[data-hg-copy-address]').forEach((button) => {
    button.addEventListener('click', async () => {
      const address = button.dataset.address || '';
      if (!address) return;
      const original = button.textContent;
      try {
        await navigator.clipboard.writeText(address);
      } catch (e) {
        const area = document.createElement('textarea');
        area.value = address;
        area.style.position = 'fixed';
        area.style.opacity = '0';
        document.body.appendChild(area);
        area.select();
        document.execCommand('copy');
        area.remove();
      }
      button.textContent = 'Copied ✓';
      setTimeout(() => { button.textContent = original; }, 1600);
    });
  });

  document.querySelectorAll('.hg-manager-fulfilment-form').forEach((form) => {
    const tracking = form.querySelector('[name="tracking_number"]');
    const shipped = form.querySelector('[data-hg-mark-shipped]');
    if (!tracking || !shipped) return;
    const sync = () => {
      shipped.disabled = !tracking.value.trim();
      shipped.title = shipped.disabled ? 'Enter tracking number first' : '';
    };
    tracking.addEventListener('input', sync);
    sync();
  });

  document.querySelectorAll('.hg-manager-login-form input[type="password"], .hg-manager-admin-form input[type="password"], .hg-manager-profile-form input[type="password"]').forEach((input) => {
    if (input.closest('.hg-password-field')) return;

    const wrapper = document.createElement('span');
    wrapper.className = 'hg-password-field';
    input.parentNode.insertBefore(wrapper, input);
    wrapper.appendChild(input);

    const toggle = document.createElement('button');
    toggle.type = 'button';
    toggle.className = 'hg-password-toggle';
    toggle.setAttribute('aria-label', 'Show password');
    toggle.setAttribute('aria-pressed', 'false');
    toggle.innerHTML = '<svg class="hg-eye-open" viewBox="0 0 24 24" aria-hidden="true"><path d="M2.5 12s3.5-6 9.5-6 9.5 6 9.5 6-3.5 6-9.5 6-9.5-6-9.5-6Z"/><circle cx="12" cy="12" r="2.7"/></svg><svg class="hg-eye-closed" viewBox="0 0 24 24" aria-hidden="true"><path d="M3 3l18 18"/><path d="M10.6 6.2A10.7 10.7 0 0 1 12 6c6 0 9.5 6 9.5 6a15.7 15.7 0 0 1-2.2 3"/><path d="M6.2 6.2C3.8 8 2.5 12 2.5 12s3.5 6 9.5 6a9.8 9.8 0 0 0 4.1-.9"/><path d="M9.9 9.9A3 3 0 0 0 14.1 14.1"/></svg>';
    wrapper.appendChild(toggle);

    toggle.addEventListener('click', () => {
      const showing = input.type === 'text';
      input.type = showing ? 'password' : 'text';
      toggle.setAttribute('aria-label', showing ? 'Show password' : 'Hide password');
      toggle.setAttribute('aria-pressed', showing ? 'false' : 'true');
      wrapper.classList.toggle('is-visible', !showing);
      input.focus({ preventScroll: true });
    });
  });

  const productForm = document.querySelector('[data-hg-product-form]');
  if (productForm) {
    const type = productForm.querySelector('[data-hg-product-type]');
    const variableOptions = productForm.querySelector('[data-hg-variable-options]');
    const syncProductType = () => {
      if (!type || !variableOptions) return;
      variableOptions.hidden = type.value !== 'variable';
    };
    if (type) {
      type.addEventListener('change', syncProductType);
      syncProductType();
    }

    const imageInput = productForm.querySelector('[data-hg-product-images]');
    const preview = productForm.querySelector('[data-hg-image-preview]');
    if (imageInput && preview) {
      imageInput.addEventListener('change', () => {
        preview.innerHTML = '';
        const files = Array.from(imageInput.files || []).slice(0, 6);
        if (!files.length) {
          preview.innerHTML = '<span>No images selected</span>';
          return;
        }
        files.forEach((file) => {
          if (!file.type.startsWith('image/')) return;
          const img = document.createElement('img');
          img.alt = file.name;
          img.src = URL.createObjectURL(file);
          img.onload = () => URL.revokeObjectURL(img.src);
          preview.appendChild(img);
        });
      });
    }
  }

  document.querySelectorAll('[data-hg-role-select]').forEach((select) => {
    const form = select.closest('form');
    const permissions = form ? form.querySelector('[data-hg-permissions]') : null;
    if (!permissions) return;

    const syncRolePermissions = () => {
      const owner = select.value === 'owner';
      permissions.classList.toggle('is-owner-disabled', owner);
      permissions.querySelectorAll('input[type="checkbox"]').forEach((checkbox) => {
        checkbox.disabled = owner;
      });
      permissions.setAttribute('aria-disabled', owner ? 'true' : 'false');
    };

    select.addEventListener('change', syncRolePermissions);
    syncRolePermissions();
  });

  const setupForm = document.querySelector('[data-hg-admin-setup]');
  if (setupForm) {
    setupForm.addEventListener('submit', async (event) => {
      event.preventDefault();

      const submit = setupForm.querySelector('[data-hg-admin-setup-submit]');
      const status = setupForm.querySelector('[data-hg-admin-setup-status]');
      const restUrl = setupForm.dataset.restUrl || '';
      const data = new FormData(setupForm);
      const password = String(data.get('password') || '');
      const confirm = String(data.get('password_confirm') || '');

      const showStatus = (message, type = 'error') => {
        if (!status) return;
        status.hidden = false;
        status.textContent = message;
        status.classList.toggle('is-error', type === 'error');
        status.classList.toggle('is-success', type === 'success');
      };

      if (password.length < 12) {
        showStatus('Password must be at least 12 characters.');
        return;
      }
      if (password !== confirm) {
        showStatus('The two passwords do not match.');
        return;
      }
      if (!restUrl) {
        showStatus('The secure setup service is unavailable. Please refresh the page and try again.');
        return;
      }

      if (submit) {
        submit.disabled = true;
        submit.dataset.originalText = submit.innerHTML;
        submit.textContent = 'Saving password…';
      }
      showStatus('Saving and verifying your password…', 'success');

      try {
        const response = await fetch(restUrl, {
          method: 'POST',
          credentials: 'same-origin',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            setup_key: String(data.get('setup_key') || ''),
            password,
            password_confirm: confirm
          })
        });
        const payload = await response.json().catch(() => ({}));

        if (!response.ok || !payload.success) {
          throw new Error(payload && payload.message ? payload.message : 'HomeGlo could not save the password.');
        }

        showStatus('Password saved and verified. Opening your Admin dashboard…', 'success');
        window.location.assign(payload.redirect || '/account/');
      } catch (error) {
        showStatus(error && error.message ? error.message : 'HomeGlo could not save the password. Please try again.');
        if (submit) {
          submit.disabled = false;
          submit.innerHTML = submit.dataset.originalText || 'Set password & open Admin';
        }
      }
    });
  }
});
